111	function runInstaller(installer: string, env: NodeJS.ProcessEnv) {
112	  return spawnSync('sh', ['-s'], { env, input: readFileSync(installer, 'utf8'), encoding: 'utf8', timeout: 30_000 });
113	}

115	function freshZsh(f: ReturnType<typeof fixture>) {
116	  const result = spawnSync('zsh', ['-i', '-c', 'command -v ax && ax version'], {
117	    cwd: f.root, env: { ...f.env, PATH: '/usr/bin:/bin' }, encoding: 'utf8', timeout: 10_000,
118	  });
119	  if (result.error) throw result.error;
120	  return result;
121	}

